'use strict';

// MODULES //

var copyJSON = require( './../utils/copy_json.js' );
var signalName = require( './../utils/signal_name.js' );


// MAIN //

/**
* Returns a transformed visualization specification which replaces property values with signals for use in conjunction with UI components.
*
* @private
* @param {Object} schema - visualization specification
* @returns {Object} transformed specification
*/
function transform( schema ) {
	var signals;
	var out;

	out = copyJSON( schema );
	signals = out.signals || [];

	// FIXME: if a value is a signal, we want the initial signal value. We can use the view.signal API (https://vega.github.io/vega/docs/api/view/#view_signal), but we first need to generate the data flow graph so that the value can be dynamically determined. So maybe what we do is we first render the "raw schema", then, upon setting up the editor, we create our new wired up schema, which we then use to re-render the visualization. **UPDATE**: this only works if a signal is a name, NOT an expression. In which case, as hinted at in the next comment, we should just skip values with signal references.

	// FIXME: we need to determine how we want to handle values already having signals, as Vega does not explicitly allow for values to have multiple signal inputs. In principle, we could just blow them away, as we'll be replacing with our own, but a user may expect the default Vega behavior. **Update**: based on how we are doing things in `editor/config`, we are skipping properties with existing signals.

	// NOTE: default values should mirror, as much as possible, the default behavior of Vega
	signals.push({
		'name': signalName( 'background' ),
		'value': out.background || '#fff'
	});
	out.background = {
		'signal': signalName( 'background' )
	};
	signals.push({
		'name': signalName( 'description' ),
		'value': out.description || ''
	});
	out.description = {
		'signal': signalName( 'description' )
	};

	signals.push({
		'name': signalName( 'title/align' ),
		'value': out.title.align || 'center'
	});
	out.title.align = {
		'signal': signalName( 'title/align' )
	};
	signals.push({
		'name': signalName( 'title/anchor' ),
		'value': out.title.anchor || 'middle'
	});
	out.title.anchor = {
		'signal': signalName( 'title/anchor' )
	};
	signals.push({
		'name': signalName( 'title/angle' ),
		'value': out.title.angle || 0
	});
	out.title.angle = {
		'signal': signalName( 'title/angle' )
	};
	signals.push({
		'name': signalName( 'title/baseline' ),
		'value': out.title.baseline || 'alphabetic'
	});
	out.title.baseline = {
		'signal': signalName( 'title/baseline' )
	};
	signals.push({
		'name': signalName( 'title/color' ),
		'value': out.title.color || '#000'
	});
	out.title.color = {
		'signal': signalName( 'title/color' )
	};
	signals.push({
		'name': signalName( 'title/dx' ),
		'value': out.title.dx || 0
	});
	out.title.dx = {
		'signal': signalName( 'title/dx' )
	};
	signals.push({
		'name': signalName( 'title/dy' ),
		'value': out.title.dy || 0
	});
	out.title.dy = {
		'signal': signalName( 'title/dy' )
	};
	signals.push({
		'name': signalName( 'title/font' ),
		'value': out.title.font || 'sans-serif'
	});
	out.title.font = {
		'signal': signalName( 'title/font' )
	};
	signals.push({
		'name': signalName( 'title/fontSize' ),
		'value': out.title.fontSize || 11
	});
	out.title.fontSize = {
		'signal': signalName( 'title/fontSize' )
	};
	signals.push({
		'name': signalName( 'title/fontStyle' ),
		'value': out.title.fontStyle || 'normal'
	});
	out.title.fontStyle = {
		'signal': signalName( 'title/fontStyle' )
	};
	signals.push({
		'name': signalName( 'title/fontWeight' ),
		'value': out.title.fontWeight || 'normal'
	});
	out.title.fontWeight = {
		'signal': signalName( 'title/fontWeight' )
	};
	signals.push({
		'name': signalName( 'title/frame' ),
		'value': out.title.frame || 'bounds'
	});
	out.title.frame = {
		'signal': signalName( 'title/frame' )
	};
	signals.push({
		'name': signalName( 'title/limit' ),
		'value': out.title.limit || 10000
	});
	out.title.limit = {
		'signal': signalName( 'title/limit' )
	};
	signals.push({
		'name': signalName( 'title/lineHeight' ),
		'value': out.title.lineHeight || 1
	});
	out.title.lineHeight = {
		'signal': signalName( 'title/lineHeight' )
	};
	signals.push({
		'name': signalName( 'title/offset' ),
		'value': out.title.offset || 0
	});
	out.title.offset = {
		'signal': signalName( 'title/offset' )
	};
	signals.push({
		'name': signalName( 'title/orient' ),
		'value': out.title.orient || 'top'
	});
	out.title.orient = {
		'signal': signalName( 'title/orient' )
	};
	signals.push({
		'name': signalName( 'title/subtitle' ),
		'value': out.title.subtitle || ''
	});
	out.title.subtitle = {
		'signal': signalName( 'title/subtitle' )
	};
	signals.push({
		'name': signalName( 'title/subtitleColor' ),
		'value': out.title.subtitleColor || '#000'
	});
	out.title.subtitleColor = {
		'signal': signalName( 'title/subtitleColor' )
	};
	signals.push({
		'name': signalName( 'title/subtitleFont' ),
		'value': out.title.subtitleFont || 'sans-serif'
	});
	out.title.subtitleFont = {
		'signal': signalName( 'title/subtitleFont' )
	};
	signals.push({
		'name': signalName( 'title/subtitleFontSize' ),
		'value': out.title.subtitleFontSize || 11
	});
	out.title.subtitleFontSize = {
		'signal': signalName( 'title/subtitleFontSize' )
	};
	signals.push({
		'name': signalName( 'title/subtitleFontStyle' ),
		'value': out.title.subtitleFontStyle || 'normal'
	});
	out.title.subtitleFontStyle = {
		'signal': signalName( 'title/subtitleFontStyle' )
	};
	signals.push({
		'name': signalName( 'title/subtitleFontWeight' ),
		'value': out.title.subtitleFontWeight || 'normal'
	});
	out.title.subtitleFontWeight = {
		'signal': signalName( 'title/subtitleFontWeight' )
	};
	signals.push({
		'name': signalName( 'title/subtitleLineHeight' ),
		'value': out.title.subtitleLineHeight || 1
	});
	out.title.subtitleLineHeight = {
		'signal': signalName( 'title/subtitleLineHeight' )
	};
	signals.push({
		'name': signalName( 'title/subtitlePadding' ),
		'value': out.title.subtitlePadding || 0
	});
	out.title.subtitlePadding = {
		'signal': signalName( 'title/subtitlePadding' )
	};
	signals.push({
		'name': signalName( 'title/text' ),
		'value': out.title.text || ''
	});
	out.title.text = {
		'signal': signalName( 'title/text' )
	};

	out.signals = signals;

	return out;
}


// EXPORTS //

module.exports = transform;
